To identify the participial phrase functioning as the subject complement in a sentence using C++ code, you can follow these steps:

1. Tokenize the sentence.
2. Iterate through tokens to identify the gerund (verb ending in -ing or -ed) or past participle (verb ending in -en or -ed).
3. Extract the words in the participial phrase, typically starting with the participle and ending before the comma or the main verb of the sentence.

In this provided sentence, the participial phrase is "Amazed by the beautiful sunset," which describes the couple.

Here's a simple C++ code example using the given sentence:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <vector>
#include <regex>

std::vector<std::string> tokenize(std::string sentence) {
    std::stringstream ss(sentence);
    std::vector<std::string> tokens;
    std::string token;

    while (getline(ss, token, ' ')) {
        tokens.push_back(token);
    }

    return tokens;
}

std::string findParticipialPhrase(std::vector<std::string> tokens) {
    std::string result = "";
    std::regex participle("((ed|ing)$)");

    for (auto word : tokens) {
        if (std::regex_search(word, participle)) {
            result += word;
            result += " ";
            continue;
        }
        if (!result.empty()) {
            result += word;
            result += " ";
            if (word.back() == ',') {
                break;
            }
        }
    }

    return result;
}

int main() {
    std::string sentence = "Amazed by the beautiful sunset, the couple sat silently on the beach.";

    std::vector<std::string> tokens = tokenize(sentence);

    std::string participialPhrase = findParticipialPhrase(tokens);

    std::cout << "Participial Phrase: " << participialPhrase << std::endl;

    return 0;
}
```

This code will output:

```
Participial Phrase: Amazed by the beautiful sunset,
```

