import time
from collections import deque

class Game:
    def __init__(self):
        self.board = [
            ['-', '-', '-', '-', '-'],
            ['-', 'X', '-', 'X', '-'],
            ['-', '-', '-', '-', '-'],
            ['-', 'X', '-', 'X', '-'],
            ['P', '-', '-', '-', '-']
        ]
        self.log = deque(maxlen=len(self.board)**2)
        self.player_position = (len(self.board) - 1, 0)
        self.start_time = time.time()

    def display_board(self):
        for row in self.board:
            print(" ".join(row))
        print("\n")

    def display_log(self):
        print("Previous positions:")
        for i, pos in enumerate(self.log):
            print(f"{i+1}. ({pos[0]}, {pos[1]})")

    def move_up(self):
        x, y = self.player_position
        if x - 1 >= 0 and self.board[x - 1][y] != 'X':  # Check for obstacle
            self.board[x][y] = '-'
            self.board[x - 1][y] = 'P'
            self.log.append(self.player_position)
            self.player_position = (x - 1, y)
            return True
        else:
            print("Error: Cannot move up due to an obstacle")
            return False

    def check_win(self):
        if self.player_position[0] == 0:
            return True
        return False

    def play(self):
        self.display_board()
        while True:
            move = input("Enter your move (up): ")
            if move.lower() == 'up':
                success = self.move_up()
                if success:
                    self.display_board()
                    if self.check_win():
                        print("Congratulations! You've reached the top!")
                        print(f"Elapsed time: {time.time() - self.start_time:.2f} seconds")
                        break
                self.display_log()
            else:
                print("Invalid input, try again.")


if __name__ == "__main__":
