module bilinear_interpolation(
    input [7:0] pixel_data[7:0], // 8x8 input image
    output [15:0] resized_data[15:0] // 16x16 resized image
);

reg [7:0] interp_a, interp_b;
integer i, j, x, y;
integer src_x, src_y;
real dx, dy, scale_x, scale_y;

initial begin
    scale_x = 8.0 / 16.0; // scaling factor for horizontal direction
    scale_y = 8.0 / 16.0; // scaling factor for vertical direction

    for (i = 0; i < 16; i = i + 1) begin
        for (j = 0; j < 16; j = j + 1) begin
            x = i * scale_x;
            y = j * scale_y;
            dx = (i * scale_x) - x;
            dy = (j * scale_y) - y;
            src_x = x;
            src_y = y;

