const content = 'This is a typing animation effect.';
const typewriterElement = document.getElementById('typewriter');
const cursorStyle = '<span class="cursor">|</span>';
const typingSpeed = 100;
let currentCharacterIndex = 0;

function type() {
    if (currentCharacterIndex < content.length) {
        typewriterElement.innerHTML = content.slice(0, currentCharacterIndex + 1) + cursorStyle;
        currentCharacterIndex++;
        setTimeout(type, typingSpeed);
    } else {
        typewriterElement.innerHTML = content + cursorStyle;
    }
}

function isInViewport(element) {
    const rect = element.getBoundingClientRect();
    return (
        rect.top >= 0 &&
        rect.left >= 0 &&
        rect.bottom <= (window.innerHeight || document.documentElement.clientHeight) &&
        rect.right <= (window.innerWidth || document.documentElement.clientWidth)
    );
}

function handleScroll() {
    if (isInViewport(typewriterElement) && currentCharacterIndex < content.length) {
        type();
        window.removeEventListener('scroll', handleScroll);
    }
}

document.addEventListener('DOMContentLoaded', () => {
    type();
    window.addEventListener('scroll', handleScroll);
