    if ($mysqli->connect_errno) {
        echo "Failed to connect to database (" . $mysqli->connect_errno . "): " . $mysqli->connect_error;
        continue;
    }

    $query = "SELECT c.id AS category_id, c.name AS category_name, sc.id AS subcategory_id, sc.name AS subcategory_name, i.id AS item_id, i.name AS item_name FROM categories c LEFT JOIN subcategories sc ON c.id = sc.category_id LEFT JOIN items i ON sc.id = i.subcategory_id";

