            if ($subcatIdx === false) {
                $subcatIdx = count($data[$catIdx]['subcategories']);
                $data[$catIdx]['subcategories'][] = [
                    'id' => $row['subcategory_id'],
                    'name' => $row['subcategory_name'],
                    'items' => [],
                ];
            }

            $data[$catIdx]['subcategories'][$subcatIdx]['items'][] = [
                'id' => $row['item_id'],
                'name' => $row['item_name'],
            ];
        }

        $result->close();
    } else {
        echo "Error executing query: " . $mysqli->error;
    }

