let max = 100;

function askForRange() {
    rl.question("Please enter the minimum and maximum range for the guessing game, separated by a space (e.g. 1 100): ", function (input) {
        const [minInput, maxInput] = input.split(' ').map(Number);
        if (minInput < maxInput) {
            min = minInput;
            max = maxInput;
            startGuessing();
        } else {
            console.log("Invalid range, please try again!");
            askForRange();
        }
    });
}

function startGuessing() {
    const guess = Math.ceil((min + max) / 2);
    rl.question(`My guess is ${guess}. Is it more, less or equal? `, function (response) {
        if (response.toLowerCase() === "more") {
            min = guess + 1;
            startGuessing();
        } else if (response.toLowerCase() === "less") {
            max = guess - 1;
            startGuessing();
        } else if (response.toLowerCase() === "equal") {
            console.log(`Yay! I've guessed the number: ${guess}`);
            rl.close();
        } else {
            console.log("Invalid response. Please answer with 'more', 'less' or 'equal'.");
            startGuessing();
        }
    });
}

